<?php
declare(strict_types=1);
date_default_timezone_set('America/New_York');

const REAL_FILE_NAME = 'install_weekly_standings_scrollbar_reserve_v003_20260922_035135am.php';
const REAL_FILE_SHA256 = '687ad226631c13cc359b59aec1721275dc5344c7f449b51a1347fdce969d708a';
const REAL_FILE_B64 = '';

function h($v): string {
    return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8');
}

function lint_php_file(string $path): array {
    if (!function_exists('shell_exec')) {
        return ['ok'=>false,'output'=>'shell_exec() is not available.'];
    }
    $out = @shell_exec('php -l ' . escapeshellarg($path) . ' 2>&1');
    if ($out === null) {
        return ['ok'=>false,'output'=>'[NULL returned by shell_exec()]'];
    }
    $out = trim((string)$out);
    return ['ok'=>stripos($out,'No syntax errors detected') !== false,'output'=>$out];
}

$realPath = __DIR__ . '/' . REAL_FILE_NAME;
$action = (string)($_POST['action'] ?? '');
$message = '';
$lint = null;

if ($action === 'stage') {
    $payload = base64_decode(REAL_FILE_B64, true);

    if ($payload === false || hash('sha256', $payload) !== REAL_FILE_SHA256) {
        $message = 'FAIL — embedded installer verification failed.';
    } else {
        if (is_file($realPath)) {
            $existing = (string)@file_get_contents($realPath);
            if (hash('sha256', $existing) !== REAL_FILE_SHA256) {
                $message = 'FAIL — a different file already exists with this installer filename.';
            }
        }

        if ($message === '' && !is_file($realPath)) {
            if (@file_put_contents($realPath, $payload, LOCK_EX) === false) {
                $message = 'FAIL — could not stage the real installer.';
            } else {
                @chmod($realPath, 0644);
            }
        }

        if ($message === '') {
            $lint = lint_php_file($realPath);
            $message = !empty($lint['ok'])
                ? 'PASS — real installer staged, hash-matched, and PHP lint passed.'
                : 'FAIL — real installer lint failed.';
        }
    }
}

if ($lint === null && is_file($realPath) && hash_file('sha256', $realPath) === REAL_FILE_SHA256) {
    $lint = lint_php_file($realPath);
}

$ready = is_file($realPath)
    && $lint !== null
    && !empty($lint['ok'])
    && hash_file('sha256', $realPath) === REAL_FILE_SHA256;
?>
<!doctype html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Weekly Standings Scrollbar Reserve v003 Lint Gate</title>
<style>
body{background:#101010;color:#eee;font-family:Arial;padding:22px}
.card{background:#1b1b1b;padding:16px;border-radius:14px;margin:14px 0}
button,a{padding:10px 16px;border-radius:9px;border:0;color:#fff;background:#248c4b;text-decoration:none;font-weight:700}
a{background:#276fca}
pre{white-space:pre-wrap;background:#111;padding:12px}
</style>
</head>
<body>
<h1>Weekly Standings Scrollbar Reserve v003 Lint Gate</h1>
<div class="card">
<p><code><?php echo h(REAL_FILE_NAME); ?></code></p>
<p><?php echo h($message); ?></p>
<?php if ($lint !== null): ?><pre><?php echo h($lint['output']); ?></pre><?php endif; ?>
<form method="post" style="display:inline">
<input type="hidden" name="action" value="stage">
<button>Stage + Lint Real Installer</button>
</form>
<?php if ($ready): ?><a href="<?php echo h(REAL_FILE_NAME); ?>">Open Real Installer</a><?php endif; ?>
</div>
</body>
</html>
